const routes = {
home: renderHome,
about: renderAbout,
services: renderServices,
technology: renderTechnology,
results: renderResults,
faq: renderFaq,
journal: renderJournal,
contact: renderContact,
privacy: renderPrivacy,
terms: renderTerms,
};
function applyChrome() {
var nl = currentLang === 'nl';
document.documentElement.lang = nl ? 'nl' : 'en';
var set = function(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; };
set('skipLink', nl ? 'Ga naar inhoud' : 'Skip to content');
set('cookieAccept', nl ? 'Accepteren' : 'Accept');
set('cookieDecline', nl ? 'Weigeren' : 'Decline');
set('nl-m-book', t('navBook'));
set('nl-m-scan', t('navScan'));
var nav = document.getElementById('siteNav'); if (nav) nav.setAttribute('aria-label', nl ? 'Hoofdnavigatie' : 'Main navigation');
var banner = document.getElementById('cookieBanner'); if (banner) banner.setAttribute('aria-label', nl ? 'Cookie-instellingen' : 'Cookie settings');
var text = document.getElementById('cookieText');
if (text) {
var link = '<a href="#" onclick="event.preventDefault(); navigate(\'privacy\')" style="color:inherit; text-decoration:underline;">' + (nl ? 'cookiebeleid' : 'cookie policy') + '</a>';
text.innerHTML = nl ? 'Wij gebruiken cookies om je ervaring te verbeteren. Door verder te gaan ga je akkoord met ons ' + link + '.' : 'We use cookies to improve your experience. By continuing you agree to our ' + link + '.';
}
}
let _isInitialLoad = true;
function navigate(route) {
currentRoute = route;
applyChrome();
closeMobile();
const app = document.getElementById('app');
app.innerHTML = '';
const el = document.createElement('div');
el.className = 'page-enter';
el.innerHTML = routes[route] ? routes[route]() : renderHome();
app.appendChild(el);
const footer = document.createElement('footer');
footer.className = 'site';
footer.innerHTML = renderFooter();
app.appendChild(footer);
const navLabels = {
home: t('navHome'), about: t('navAbout'), services: t('navServices'),
technology: t('navTech'), faq:'FAQ', journal:'Journal', contact:'Contact'
};
document.querySelectorAll('.nav-links a').forEach(a => {
a.classList.toggle('active', a.dataset.route === route);
if (navLabels[a.dataset.route]) a.textContent = navLabels[a.dataset.route];
});
const scanBtn = document.getElementById('nl-scan');
const bookBtn = document.getElementById('nl-book');
if (scanBtn) scanBtn.textContent = t('navScan');
if (bookBtn) bookBtn.textContent = t('navBook');
const darkOpener = route === 'home' || route === 'results';
document.getElementById('siteNav').classList.toggle('on-dark', darkOpener);
window.scrollTo(0, 0);
document.getElementById('app').focus({preventScroll: true});
if (_isInitialLoad) { _isInitialLoad = false; } else { const langPrefix = currentLang === "en" ? "en/" : ""; if (route === "home" && currentLang === "nl") { history.pushState(null, "", window.location.pathname); } else { history.pushState(null, "", "#" + langPrefix + route); } }
bindPageInteractions();
}
function bindPageInteractions() {
document.querySelectorAll('[data-route]').forEach(el => {
if (!el._routeBound) {
el._routeBound = true;
el.onclick = (e) => { e.preventDefault(); navigate(el.dataset.route); };
}
});
document.querySelectorAll('.faq-item').forEach(it => {
it.onclick = () => it.classList.toggle('open');
});
document.querySelectorAll('[data-book]').forEach(el => {
el.onclick = (e) => { e.preventDefault(); closeMobile(); openBooking(el.dataset.book || null); };
});
}
var BOOKING_MODE = 'waitlist';
try { if (/[?&]booking=test(&|$)/.test(window.location.search)) BOOKING_MODE = 'test'; } catch (e) {}
var FORM_ENDPOINT = 'https://formspree.io/f/xzdodkva';
let bookingStep = 1;
let bookingSending = false;
function newBookingData() {
return { service: null, gender: 'women', areas: [], pref: [], date: null, slot: null, firstName: '', lastName: '', email: '', phone: '', note: '', consent: false };
}
let bookingData = newBookingData();
function bk(key) {
var nl = currentLang === 'nl';
var S = {
step1Title: nl ? 'Waar ben je in <i>geïnteresseerd?</i>' : 'What are you <i>interested in?</i>',
step1Sub: nl ? 'We openen in het tweede kwartaal van 2027. Kies je behandeling en kom op de wachtlijst.' : 'We open in the second quarter of 2027. Choose your treatment and join the waiting list.',
next: nl ? 'Verder →' : 'Continue →',
women: nl ? 'Dames' : 'Women',
men: nl ? 'Heren' : 'Men',
areaHint: nl ? 'Kies één of meer zones. Prijzen per sessie, inclusief 21% btw.' : 'Choose one or more areas. Prices per session, including 21% VAT.',
selNone: nl ? 'Nog geen zone gekozen. Weet je het nog niet? Ga gerust verder.' : 'No area chosen yet. Not sure? Feel free to continue.',
selLabel: nl ? 'Jouw selectie' : 'Your selection',
perSession: nl ? 'Per sessie' : 'Per session',
pkg6: nl ? 'Pakket 5+1 (6 sessies)' : 'Package 5+1 (6 sessions)',
pkg13: nl ? 'Pakket 10+3 (13 sessies)' : 'Package 10+3 (13 sessions)',
indication: nl ? 'Dit is een indicatie. Je behandelplan en de definitieve prijs bespreken we tijdens de gratis huidscan.' : 'This is an indication. We discuss your treatment plan and the final price during the free skin scan.',
pricing: nl ? 'Tarieven' : 'Pricing',
recommended: nl ? 'Aanbevolen bij een eerste bezoek' : 'Recommended for first-time visitors',
step3Sub: nl ? 'Zo bereiken we je zodra de agenda opengaat.' : 'So we can reach you as soon as booking opens.',
required: nl ? '* Verplicht' : '* Required',
firstName: nl ? 'Voornaam' : 'First name',
lastName: nl ? 'Achternaam' : 'Last name',
phoneOpt: nl ? 'Telefoon (optioneel)' : 'Phone (optional)',
prefLabel: nl ? 'Wanneer komt een afspraak je het best uit? (optioneel)' : 'When would an appointment suit you best? (optional)',
noteLabel: nl ? 'Vragen of wensen? (optioneel)' : 'Questions or wishes? (optional)',
notePh: nl ? 'Andere zones, eerdere behandelingen, vragen...' : 'Other areas, earlier treatments, questions...',
consent: nl ? 'Ja, zet mij op de wachtlijst. SkinTech Laser Clinic mag mij één bericht sturen zodra ik een afspraak kan maken.' : 'Yes, put me on the waiting list. SkinTech Laser Clinic may send me one message as soon as I can book an appointment.',
consentSmall: nl ? 'We gebruiken je gegevens alleen hiervoor. Meer lees je in ons ' : 'We use your details for this purpose only. Read more in our ',
privacy: nl ? 'privacybeleid' : 'privacy policy',
submit: nl ? 'Zet me op de wachtlijst →' : 'Join the waiting list →',
sending: nl ? 'Bezig met verzenden...' : 'Sending...',
error: nl ? 'Verzenden is niet gelukt. Probeer het opnieuw of mail ons op info@skintechclinic.nl.' : 'Sending failed. Please try again or email us at info@skintechclinic.nl.',
doneTitle: nl ? 'Je staat op de <i>wachtlijst.</i>' : 'You are on the <i>waiting list.</i>',
doneText1: nl ? 'We openen naar verwachting in het tweede kwartaal van 2027. Zodra de agenda opengaat, sturen we één persoonlijk bericht naar' : 'We expect to open in the second quarter of 2027. As soon as booking opens, we will send one personal message to',
doneText2: nl ? 'Je ontvangt ook een bevestiging per e-mail.' : 'You will also receive a confirmation by email.',
areasLabel: nl ? 'Zones' : 'Areas',
testSub: nl ? 'Wij hebben je voorkeur ontvangen en nemen zo snel mogelijk contact met je op via' : 'We have received your preference and will contact you as soon as possible at',
testNote: nl ? 'Dit is een voorkeur, geen definitieve afspraak. Wij bevestigen je boeking per e-mail.' : 'This is a preference, not a confirmed appointment. We will confirm your booking by email.'
};
return S[key];
}
var BOOKING_PREFS = [
{ id: 'weekday_day', nl: 'Doordeweeks overdag', en: 'Weekdays, daytime' },
{ id: 'weekday_evening', nl: 'Doordeweeks ’s avonds', en: 'Weekday evenings' },
{ id: 'saturday', nl: 'Zaterdag', en: 'Saturday' }
];
function bookingSvc() {
var svcs = currentLang === 'en' ? SERVICES_EN : SERVICES;
return bookingData.service ? svcs.find(function(s) { return s.id === bookingData.service; }) : null;
}
function bookingMoney(n) {
var s = String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, currentLang === 'nl' ? '.' : ',');
return '€' + s;
}
function bookingSelection() {
var svc = bookingSvc();
var out = { names: [], total: 0 };
if (!svc || !svc.laserPricing) return out;
var lp = svc.laserPricing[bookingData.gender] || svc.laserPricing.women;
bookingData.areas.forEach(function(id) {
var p = id.split(':');
var row = lp[p[0]] && lp[p[0]][parseInt(p[1], 10)];
if (row) { out.names.push(row.area); out.total += parseInt(row.single.replace(/[^\d]/g, ''), 10); }
});
return out;
}
function openBooking(serviceId) {
bookingOpen = true;
bookingStep = 1;
bookingSending = false;
bookingData = newBookingData();
var svcs = currentLang === 'en' ? SERVICES_EN : SERVICES;
if (serviceId && svcs.some(function(s) { return s.id === serviceId; })) bookingData.service = serviceId;
renderBooking();
}
function closeBooking() { bookingOpen = false; document.getElementById('modalHost').innerHTML = ''; }
function renderBooking() {
const host = document.getElementById('modalHost');
if (!bookingOpen) { host.innerHTML = ''; return; }
const steps = BOOKING_MODE === 'waitlist' ? [1, 3, 4] : [1, 2, 3, 4];
const pos = steps.indexOf(bookingStep);
host.innerHTML = `
<div class="modal-backdrop" onclick="if(event.target===this) closeBooking()">
<div class="modal" role="dialog" aria-modal="true">
<button class="close" onclick="closeBooking()" aria-label="${currentLang === 'nl' ? 'Sluiten' : 'Close'}">✕</button>
<div class="step-dots">
${steps.map(function(s, i) { return '<div class="step-dot ' + (pos >= i ? 'active' : '') + '"></div>'; }).join('')}
</div>
${bookingStep===1 ? bookingStep1() : ''}
${bookingStep===2 ? bookingStep2() : ''}
${bookingStep===3 ? bookingStep3() : ''}
${bookingStep===4 ? bookingStep4() : ''}
</div>
</div>
`;
if (bookingStep === 3) updateBookingBtn();
}
function bookingSummaryInner() {
var sel = bookingSelection();
if (!sel.names.length) return '<div class="wl-summary-empty">' + bk('selNone') + '</div>';
return '<div class="wl-summary-title">' + bk('selLabel') + ': ' + sel.names.join(', ') + '</div>' +
'<div class="wl-summary-row"><span>' + bk('perSession') + '</span><strong>' + bookingMoney(sel.total) + '</strong></div>' +
'<div class="wl-summary-row"><span>' + bk('pkg6') + '</span><span>' + bookingMoney(sel.total * 5) + '</span></div>' +
'<div class="wl-summary-row"><span>' + bk('pkg13') + '</span><span>' + bookingMoney(sel.total * 10) + '</span></div>' +
'<div class="wl-summary-note">' + bk('indication') + '</div>';
}
function toggleBookingArea(id, el) {
var i = bookingData.areas.indexOf(id);
if (i === -1) bookingData.areas.push(id); else bookingData.areas.splice(i, 1);
if (el && el.parentElement) el.parentElement.classList.toggle('on', i === -1);
var box = document.getElementById('wl-summary');
if (box) box.innerHTML = bookingSummaryInner();
}
function setBookingGender(g) {
if (bookingData.gender === g) return;
bookingData.gender = g;
bookingData.areas = [];
renderBooking();
}
function toggleBookingPref(id, el) {
var i = bookingData.pref.indexOf(id);
if (i === -1) bookingData.pref.push(id); else bookingData.pref.splice(i, 1);
if (el) { el.classList.toggle('on', i === -1); el.setAttribute('aria-pressed', i === -1 ? 'true' : 'false'); }
}
function bookingStep1() {
const svcs = currentLang==='en' ? SERVICES_EN : SERVICES;
const selectedSvc = bookingSvc();
var detail = '';
if (selectedSvc && selectedSvc.laserPricing) {
var lp = selectedSvc.laserPricing[bookingData.gender] || selectedSvc.laserPricing.women;
var catLabels = currentLang==='nl'
? {face:'Gezicht',upperBody:'Bovenlichaam',bikini:'Bikini / intiem',legs:'Benen',lowerBody:'Onderlichaam',combos:'Combinaties'}
: {face:'Face',upperBody:'Upper body',bikini:'Bikini / intimate',legs:'Legs',lowerBody:'Lower body',combos:'Combinations'};
var rows = '';
Object.keys(lp).forEach(function(cat) {
rows += '<div class="wl-cat">' + (catLabels[cat] || cat) + '</div>';
lp[cat].forEach(function(r, i) {
var id = cat + ':' + i;
var on = bookingData.areas.indexOf(id) !== -1;
rows += '<label class="wl-area' + (on ? ' on' : '') + '">' +
'<input type="checkbox" ' + (on ? 'checked ' : '') + 'onchange="toggleBookingArea(\'' + id + '\', this)">' +
'<span class="wl-area-name">' + r.area + '</span>' +
'<span class="wl-area-price">' + r.single + '</span>' +
'</label>';
});
});
detail = '<div class="wl-panel">' +
'<div class="wl-toggle">' +
'<button type="button" class="btn ' + (bookingData.gender==='women' ? 'btn-primary' : 'btn-ghost') + '" onclick="setBookingGender(\'women\')">' + bk('women') + '</button>' +
'<button type="button" class="btn ' + (bookingData.gender==='men' ? 'btn-primary' : 'btn-ghost') + '" onclick="setBookingGender(\'men\')">' + bk('men') + '</button>' +
'</div>' +
'<p class="wl-hint">' + bk('areaHint') + '</p>' +
'<div class="wl-areas">' + rows + '</div>' +
'<div class="wl-summary" id="wl-summary">' + bookingSummaryInner() + '</div>' +
'</div>';
} else if (selectedSvc && selectedSvc.pricing) {
detail = '<div class="wl-panel">' +
'<div class="wl-cat" style="margin-top:0;">' + bk('pricing') + ' · ' + selectedSvc.name + '</div>';
selectedSvc.pricing.forEach(function(p) {
detail += '<div class="wl-price-row"><span>' + p.label + '</span><span>' + p.value + '</span></div>';
});
if (selectedSvc.priceNote) detail += '<div class="wl-summary-note">' + selectedSvc.priceNote + '</div>';
detail += '</div>';
}
const test = BOOKING_MODE !== 'waitlist';
const nextStep = test ? 2 : 3;
return '<h3>' + (test ? t('bookStep1Title') : bk('step1Title')) + '</h3>' +
'<p class="sub">' + (test ? t('bookStep1Sub') : bk('step1Sub')) + '</p>' +
'<div class="svc-radio">' +
svcs.map(function(s) {
return '<div class="svc-opt ' + (bookingData.service===s.id ? 'selected' : '') + '" role="button" tabindex="0" onclick="bookingData.service=\'' + s.id + '\'; bookingData.areas=[]; renderBooking();" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault(); this.click();}">' +
'<div style="flex:1;">' +
'<div class="name">' + s.name + '</div>' +
'<div class="wl-opt-meta">' + s.duration + '</div>' +
(s.id==='scan' ? '<div class="wl-opt-rec">' + bk('recommended') + '</div>' : '') +
'</div>' +
'<div class="price">' + (s.pricing && s.pricing[0] ? s.pricing[0].value : s.sessions) + '</div>' +
'</div>';
}).join('') +
'</div>' +
detail +
'<div style="margin-top:28px; display:flex; justify-content:flex-end;">' +
'<button class="btn btn-primary" ' + (!bookingData.service ? 'disabled style="opacity:0.4; cursor:not-allowed;"' : '') + ' onclick="if(bookingData.service){bookingStep=' + nextStep + '; renderBooking();}">' + (test ? t('bookDateNext') : bk('next')) + '</button>' +
'</div>';
}
function bookingStep2() {
var upcoming = [];
var d = new Date();
d.setDate(d.getDate() + 1); // start from tomorrow
while (upcoming.length < 14) {
if (d.getDay() !== 0) { // skip Sunday
upcoming.push(new Date(d));
}
d.setDate(d.getDate() + 1);
}
var monthNames = currentLang==='nl'
? ['januari','februari','maart','april','mei','juni','juli','augustus','september','oktober','november','december']
: ['January','February','March','April','May','June','July','August','September','October','November','December'];
var dayNames = currentLang==='nl'
? ['Zo','Ma','Di','Wo','Do','Vr','Za']
: ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
var currentMonth = upcoming[0].getMonth();
var currentYear = upcoming[0].getFullYear();
var monthLabel = monthNames[currentMonth] + ' ' + currentYear;
var endMonth = upcoming[upcoming.length-1].getMonth();
if (endMonth !== currentMonth) {
monthLabel += ' / ' + monthNames[endMonth] + ' ' + upcoming[upcoming.length-1].getFullYear();
}
var timeSlots = [];
for (var h = 9; h <= 18; h++) {
for (var m = 0; m < 60; m += 15) {
if (h === 18 && m > 0) break;
timeSlots.push((h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m);
}
}
var customLabel = currentLang==='nl' ? 'Ander tijdstip...' : 'Other time...';
return `
<h3>${t('bookStep2Title')}</h3>
<p class="sub">${t('bookStep2Sub')}</p>
<div style="font-size:13px; color:var(--bronze-deep); font-family:var(--serif); margin-bottom:12px; font-style:italic;">${monthLabel}</div>
<div style="display:grid; grid-template-columns:repeat(7, 1fr); gap:8px; margin-bottom:24px;">
${upcoming.map(dt => {
var key = dt.toISOString().slice(0,10);
return '<div class="slot '+(bookingData.date===key?'selected':'')+'" onclick="bookingData.date=\''+key+'\'; renderBooking();">' +
'<div style="font-size:12px; letter-spacing:0.08em; text-transform:uppercase; color:var(--muted); margin-bottom:4px;">'+dayNames[dt.getDay()]+'</div>' +
'<div>'+dt.getDate()+'</div>' +
'</div>';
}).join('')}
</div>
<span class="eyebrow" style="display:block; margin-bottom:12px;">${t('timeLabel')}</span>
<div class="slot-grid" style="max-height:160px; overflow-y:auto; padding-right:4px;">
${timeSlots.map(tt => '<div class="slot '+(bookingData.slot===tt?'selected':'')+'" onclick="bookingData.slot=\''+tt+'\'; renderBooking();">'+tt+'</div>').join('')}
</div>
<div style="margin-top:12px;">
<input type="time" id="b-custom-time" style="font-size:14px; padding:8px 12px; border:1px solid var(--line); border-radius:4px; font-family:var(--sans);" onchange="bookingData.slot=this.value; renderBooking();" placeholder="${customLabel}" value="${bookingData.slot && !timeSlots.includes(bookingData.slot) ? bookingData.slot : ''}">
<span style="font-size:12px; color:var(--muted); margin-left:8px;">${customLabel}</span>
</div>
<div style="margin-top:28px; display:flex; justify-content:space-between;">
<button class="btn btn-ghost" onclick="bookingStep=1; renderBooking();">${t('bookBack')}</button>
<button class="btn btn-primary" ${(!bookingData.date||!bookingData.slot)?'disabled style="opacity:0.4; cursor:not-allowed;"':''} onclick="if(bookingData.date&&bookingData.slot){bookingStep=3; renderBooking();}">${t('bookDetailsNext')}</button>
</div>
`;
}
function bookingStep3() {
const test = BOOKING_MODE !== 'waitlist';
const esc = function(v) { return String(v || '').replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;'); };
const prefs = test ? '' : '<div class="form-field"><label>' + bk('prefLabel') + '</label><div class="wl-chips">' +
BOOKING_PREFS.map(function(p) {
var on = bookingData.pref.indexOf(p.id) !== -1;
return '<button type="button" class="wl-chip' + (on ? ' on' : '') + '" aria-pressed="' + (on ? 'true' : 'false') + '" onclick="toggleBookingPref(\'' + p.id + '\', this)">' + (currentLang === 'nl' ? p.nl : p.en) + '</button>';
}).join('') + '</div></div>';
const consent = test ? '' : '<label class="wl-consent"><input type="checkbox" id="b-consent" ' + (bookingData.consent ? 'checked ' : '') + 'onchange="bookingData.consent=this.checked; updateBookingBtn();">' +
'<span>' + bk('consent') + ' *<br/><small>' + bk('consentSmall') + '<a href="#" onclick="event.preventDefault(); closeBooking(); navigate(\'privacy\');">' + bk('privacy') + '</a>.</small></span></label>';
return `
<h3>${t('bookStep3Title')}</h3>
<p class="sub">${test ? t('bookStep3Sub') : bk('step3Sub')}</p>
<div class="wl-required">${bk('required')}</div>
<div class="wl-two">
<div class="form-field"><label for="b-fname">${bk('firstName')} *</label><input type="text" id="b-fname" autocomplete="given-name" value="${esc(bookingData.firstName)}" oninput="bookingData.firstName=this.value; updateBookingBtn();"></div>
<div class="form-field"><label for="b-lname">${bk('lastName')} *</label><input type="text" id="b-lname" autocomplete="family-name" value="${esc(bookingData.lastName)}" oninput="bookingData.lastName=this.value; updateBookingBtn();"></div>
</div>
<div class="form-field"><label for="b-email">${t('bookEmailLabel')} *</label><input type="email" id="b-email" autocomplete="email" value="${esc(bookingData.email)}" oninput="bookingData.email=this.value; updateBookingBtn();" placeholder="${currentLang === 'nl' ? 'naam@voorbeeld.nl' : 'name@example.com'}"></div>
<div class="form-field"><label for="b-phone">${test ? t('bookPhoneLabel') + ' *' : bk('phoneOpt')}</label><input type="tel" id="b-phone" autocomplete="tel" value="${esc(bookingData.phone)}" oninput="bookingData.phone=this.value; updateBookingBtn();" placeholder="+31 6 ..."></div>
${prefs}
<div class="form-field"><label for="b-note">${test ? t('bookNoteLabel') : bk('noteLabel')}</label><textarea id="b-note" oninput="bookingData.note=this.value;" placeholder="${test ? t('bookNotePh') : bk('notePh')}">${esc(bookingData.note)}</textarea></div>
${consent}
<div class="wl-error" id="b-error" role="alert" style="display:none;"></div>
<div style="margin-top:16px; display:flex; justify-content:space-between; gap:12px; flex-wrap:wrap;">
<button class="btn btn-ghost" onclick="bookingStep=${test ? 2 : 1}; renderBooking();">${t('bookBack')}</button>
<button class="btn btn-primary" id="b-confirm-btn" disabled style="opacity:0.4; cursor:not-allowed;" onclick="submitBooking()">${test ? t('bookConfirm') : bk('submit')}</button>
</div>
`;
}
function bookingValid() {
var test = BOOKING_MODE !== 'waitlist';
var emailValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(bookingData.email);
var phoneValid = /^[+]?[\d\s()-]{7,}$/.test(bookingData.phone);
var phoneOk = test ? (bookingData.phone && phoneValid) : (!bookingData.phone || phoneValid);
return { ok: !!(bookingData.firstName.trim() && bookingData.lastName.trim() && emailValid && phoneOk && (test || bookingData.consent)), emailValid: emailValid, phoneValid: phoneValid };
}
function updateBookingBtn() {
var btn = document.getElementById('b-confirm-btn');
if (!btn || bookingSending) return;
var v = bookingValid();
btn.disabled = !v.ok;
btn.style.opacity = v.ok ? '1' : '0.4';
btn.style.cursor = v.ok ? 'pointer' : 'not-allowed';
var emailEl = document.getElementById('b-email');
var phoneEl = document.getElementById('b-phone');
if (emailEl) emailEl.style.borderColor = bookingData.email && !v.emailValid ? '#c44' : '';
if (phoneEl) phoneEl.style.borderColor = bookingData.phone && !v.phoneValid ? '#c44' : '';
}
function submitBooking() {
if (bookingSending || !bookingValid().ok) return;
var test = BOOKING_MODE !== 'waitlist';
var nl = currentLang === 'nl';
var svc = bookingSvc();
var sel = bookingSelection();
var fullName = (bookingData.firstName + ' ' + bookingData.lastName).trim();
var fd = new FormData();
fd.append('_form_type', test ? 'booking_test' : 'waitlist');
fd.append('_subject', (test ? 'Boekingsverzoek (test) — ' : (nl ? 'Wachtlijst — ' : 'Waiting list — ')) + (svc ? svc.name : bookingData.service));
fd.append('language', currentLang);
fd.append('service', svc ? svc.name : bookingData.service);
if (svc && svc.laserPricing) {
fd.append('gender', bookingData.gender === 'men' ? bk('men') : bk('women'));
fd.append('areas', sel.names.join(', '));
if (sel.names.length) {
fd.append('price_per_session', bookingMoney(sel.total));
fd.append('package_5_plus_1', bookingMoney(sel.total * 5));
fd.append('package_10_plus_3', bookingMoney(sel.total * 10));
}
}
if (test) {
fd.append('preferred_date', bookingData.date);
fd.append('preferred_time', bookingData.slot);
} else {
fd.append('preference', BOOKING_PREFS.filter(function(p) { return bookingData.pref.indexOf(p.id) !== -1; }).map(function(p) { return nl ? p.nl : p.en; }).join(', '));
fd.append('consent_waitlist', 'yes');
fd.append('consent_text', bk('consent'));
}
fd.append('name', fullName);
fd.append('first_name', bookingData.firstName.trim());
fd.append('last_name', bookingData.lastName.trim());
fd.append('email', bookingData.email.trim());
fd.append('phone', bookingData.phone.trim());
fd.append('note', bookingData.note.trim());
var btn = document.getElementById('b-confirm-btn');
var box = document.getElementById('b-error');
var label = btn ? btn.textContent : '';
bookingSending = true;
if (box) box.style.display = 'none';
if (btn) { btn.disabled = true; btn.style.opacity = '0.6'; btn.textContent = bk('sending'); }
fetch(FORM_ENDPOINT, { method: 'POST', body: fd, headers: { 'Accept': 'application/json' } })
.then(function(r) { if (!r.ok) throw new Error('status ' + r.status); })
.then(function() { bookingSending = false; bookingStep = 4; renderBooking(); })
.catch(function() {
bookingSending = false;
if (box) { box.textContent = bk('error'); box.style.display = 'block'; }
if (btn) { btn.textContent = label; updateBookingBtn(); }
});
}
function bookingStep4() {
const test = BOOKING_MODE !== 'waitlist';
const svc = bookingSvc();
const sel = bookingSelection();
const esc = function(v) { return String(v || '').replace(/&/g, '&amp;').replace(/</g, '&lt;'); };
const row = function(label, value, last) { return '<div class="wl-done-row"' + (last ? ' style="border-bottom:0;"' : '') + '><span>' + label + '</span><strong>' + value + '</strong></div>'; };
var rows = '';
var intro = '';
var note = '';
if (test) {
var dateDisplay = bookingData.date;
try {
var dp = new Date(bookingData.date + 'T12:00:00');
var monthNames = currentLang==='nl'
? ['jan','feb','mrt','apr','mei','jun','jul','aug','sep','okt','nov','dec']
: ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
dateDisplay = dp.getDate() + ' ' + monthNames[dp.getMonth()] + ' ' + dp.getFullYear();
} catch(e){}
intro = bk('testSub') + ' ' + esc(bookingData.email) + '.';
rows = row(t('bookServiceLabel'), svc ? svc.name : '—') + row(t('bookDateLabel'), dateDisplay) + row(t('bookTimeLabel'), bookingData.slot, true);
note = bk('testNote');
} else {
intro = bk('doneText1') + ' ' + esc(bookingData.email) + '. ' + bk('doneText2');
var list = [[t('bookServiceLabel'), svc ? svc.name : '—']];
if (sel.names.length) { list.push([bk('areasLabel'), sel.names.join(', ')]); list.push([bk('perSession'), bookingMoney(sel.total)]); }
rows = list.map(function(r, i) { return row(r[0], r[1], i === list.length - 1); }).join('');
}
return `
<div style="text-align:center; padding:20px 0 12px;">
<div class="wl-check">✓</div>
<h3 style="text-align:center;">${test ? t('bookStep4Title') : bk('doneTitle')}</h3>
<p class="sub" style="text-align:center;">${intro}</p>
</div>
<div class="wl-done">${rows}</div>
${note ? '<p class="wl-done-note">' + note + '</p>' : ''}
<button class="btn btn-primary" style="width:100%; justify-content:center;" onclick="closeBooking()">${t('bookClose')}</button>
`;
}
function handleContact(e) {
e.preventDefault();
var form = e.target;
var email = form.querySelector('input[name="email"]');
var phone = form.querySelector('input[name="phone"]');
var errors = [];
if (email && email.value && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.value)) {
errors.push(currentLang === 'nl' ? 'Voer een geldig e-mailadres in.' : 'Please enter a valid email address.');
}
if (phone && phone.value && !/^[+]?[\d\s()-]{7,}$/.test(phone.value)) {
errors.push(currentLang === 'nl' ? 'Voer een geldig telefoonnummer in.' : 'Please enter a valid phone number.');
}
var honeypot = form.querySelector('input[name="_gotcha"]');
if (honeypot && honeypot.value) { return; }
if (errors.length) {
var existing = form.querySelector('.form-errors');
if (existing) existing.remove();
var errDiv = document.createElement('div');
errDiv.className = 'form-errors';
errDiv.style.cssText = 'background:var(--cream);border:1px solid #c44;border-radius:8px;padding:12px 16px;margin-bottom:16px;font-size:13px;color:#a33;line-height:1.6;';
errDiv.innerHTML = errors.join('<br>');
form.insertBefore(errDiv, form.firstChild);
return;
}
var prevErr = form.querySelector('.form-errors');
if (prevErr) prevErr.remove();
var btn = form.querySelector('button[type="submit"]');
var origText = btn.textContent;
btn.textContent = currentLang === 'nl' ? 'Verzenden...' : 'Sending...';
btn.disabled = true;
var data = new FormData(form);
fetch('https://formspree.io/f/xzdodkva', {
method: 'POST',
body: data,
headers: { 'Accept': 'application/json' }
}).then(function(r) {
if (r.ok) {
form.innerHTML = '<div style="padding:60px 0; text-align:center;">' +
'<div style="width:64px; height:64px; margin:0 auto 24px; border-radius:50%; border:1px solid var(--bronze-deep); display:grid; place-items:center; color:var(--bronze-deep); font-family:var(--serif); font-size:28px; font-style:italic;">\u2713</div>' +
'<h3 style="font-family:var(--serif); font-size:34px; font-weight:400; margin-bottom:12px;">' + (currentLang==='nl' ? 'Bedankt!' : 'Thank you!') + '</h3>' +
'<p style="color:var(--muted); font-size:15px; line-height:1.7; max-width:400px; margin:0 auto;">' + (currentLang==='nl' ? 'We hebben je bericht ontvangen en nemen zo snel mogelijk contact met je op.' : 'We have received your message and will get back to you as soon as possible.') + '</p>' +
'</div>';
} else {
btn.textContent = origText;
btn.disabled = false;
alert(currentLang === 'nl' ? 'Er ging iets mis. Probeer het opnieuw of mail info@skintechclinic.nl.' : 'Something went wrong. Please try again or email info@skintechclinic.nl.');
}
}).catch(function() {
btn.textContent = origText;
btn.disabled = false;
alert(currentLang === 'nl' ? 'Geen verbinding. Controleer je internet en probeer opnieuw.' : 'No connection. Check your internet and try again.');
});
}
function handleScroll() {
const nav = document.getElementById('siteNav');
if (window.scrollY > 40) nav.classList.add('scrolled'); else nav.classList.remove('scrolled');
}
window.addEventListener('scroll', handleScroll);
function toggleMobile() {
var links = document.querySelector('.nav-links');
var toggle = document.querySelector('.mobile-toggle');
if (!links) return;
var open = !links.classList.contains('open');
links.classList.toggle('open', open);
if (toggle) {
toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
toggle.setAttribute('aria-label', currentLang === 'nl' ? (open ? 'Menu sluiten' : 'Menu openen') : (open ? 'Close menu' : 'Open menu'));
}
}
function closeMobile() {
var links = document.querySelector('.nav-links');
var toggle = document.querySelector('.mobile-toggle');
if (links) links.classList.remove('open');
if (toggle) {
toggle.setAttribute('aria-expanded', 'false');
toggle.setAttribute('aria-label', currentLang === 'nl' ? 'Menu openen' : 'Open menu');
}
}
const TWEAKS = {
"accent": "charcoal",
"typeScale": "editorial",
"density": "spacious"
};
const ACCENTS = {
bronze: { bronze:'#B8956A', bronzeDeep:'#8C6B44', bronzePale:'#D4B896' },
charcoal: { bronze:'#6E6359', bronzeDeep:'#4A423A', bronzePale:'#B5AA9D' },
moss: { bronze:'#8A9476', bronzeDeep:'#5F6A4E', bronzePale:'#C0C8AE' },
rose: { bronze:'#B88E85', bronzeDeep:'#8C5F56', bronzePale:'#D9B9B1' },
};
function applyTweaks() {
const root = document.documentElement;
const c = ACCENTS[TWEAKS.accent] || ACCENTS.bronze;
root.style.setProperty('--bronze', c.bronze);
root.style.setProperty('--bronze-deep', c.bronzeDeep);
root.style.setProperty('--bronze-pale', c.bronzePale);
document.body.style.setProperty('font-size', TWEAKS.typeScale === 'editorial' ? '16px' : TWEAKS.typeScale === 'compact' ? '14px' : '17px');
}
function renderTweaks() {
const panel = document.getElementById('tweaksPanel');
panel.innerHTML = `
<h4>Tweaks</h4>
<div class="tweaks-sub">Live visual variations</div>
<div class="tweak-group">
<div class="tweak-label">Accent tone</div>
<div class="swatch-row">
${Object.keys(ACCENTS).map(k => `
<div class="swatch ${TWEAKS.accent===k?'active':''}" title="${k}" style="background:${ACCENTS[k].bronze}" onclick="setTweak('accent','${k}')"></div>
`).join('')}
</div>
</div>
<div class="tweak-group">
<div class="tweak-label">Type scale</div>
<div class="tweak-row">
${['compact','editorial','grand'].map(v => `
<button class="tweak-chip ${TWEAKS.typeScale===v?'active':''}" onclick="setTweak('typeScale','${v}')">${v}</button>
`).join('')}
</div>
</div>
<div class="tweak-group">
<div class="tweak-label">Density</div>
<div class="tweak-row">
${['tight','spacious','airy'].map(v => `
<button class="tweak-chip ${TWEAKS.density===v?'active':''}" onclick="setTweak('density','${v}')">${v}</button>
`).join('')}
</div>
</div>
`;
}
function setTweak(key, val) {
TWEAKS[key] = val;
applyTweaks();
renderTweaks();
try { window.parent.postMessage({type:'__edit_mode_set_keys', edits:{[key]: val}}, '*'); } catch(e){}
}
window.addEventListener('message', (e) => {
if (!e.data || !e.data.type) return;
if (e.data.type === '__activate_edit_mode') { document.getElementById('tweaksPanel').classList.add('visible'); renderTweaks(); }
if (e.data.type === '__deactivate_edit_mode') { document.getElementById('tweaksPanel').classList.remove('visible'); }
});
try { window.parent.postMessage({type:'__edit_mode_available'}, '*'); } catch(e){}
try { if(localStorage.getItem('sk_cookies')) document.getElementById('cookieBanner').classList.add('hidden'); } catch(e){}
window.addEventListener('popstate', function() {
let h = window.location.hash.replace('#','');
if (h.startsWith('en/')) { if (currentLang !== 'en') setLang('en'); h = h.slice(3); }
else if (h.startsWith('nl/')) { if (currentLang !== 'nl') setLang('nl'); h = h.slice(3); }
else if (currentLang === 'en' && !h.startsWith('en')) { setLang('nl'); }
const target = h && routes[h] ? h : 'home';
if (target !== currentRoute) {
currentRoute = target;
const app = document.getElementById('app');
app.innerHTML = '';
const el = document.createElement('div');
el.className = 'page-enter';
el.innerHTML = routes[target] ? routes[target]() : renderHome();
app.appendChild(el);
const footer = document.createElement('footer');
footer.className = 'site';
footer.innerHTML = renderFooter();
app.appendChild(footer);
const darkOpener = target === 'home' || target === 'results';
document.getElementById('siteNav').classList.toggle('on-dark', darkOpener);
window.scrollTo(0, 0);
document.getElementById('app').focus({preventScroll: true});
bindPageInteractions();
}
});
applyTweaks();
let hashRaw = window.location.hash.replace('#','');
if (hashRaw.startsWith('en/')) { currentLang = 'en'; try { localStorage.setItem('sk_lang','en'); } catch(e){} hashRaw = hashRaw.slice(3); }
else if (hashRaw.startsWith('en')) { currentLang = 'en'; try { localStorage.setItem('sk_lang','en'); } catch(e){} if (hashRaw === 'en') hashRaw = 'home'; }
var initArticle = null;
if (!hashRaw) {
var pathParts = window.location.pathname.slice(1).split('/');
var path = pathParts[0];
if (path && routes[path]) hashRaw = path;
if (path === 'journal' && pathParts[1] && ARTICLES.some(function(a) { return a.id === pathParts[1]; })) initArticle = pathParts[1];
}
const hashRoute = hashRaw;
const initRoute = hashRoute && routes[hashRoute] ? hashRoute : 'home';
currentRoute = initRoute;
navigate(initRoute);
if (initArticle) showArticle(initArticle);
window._jsLoaded = true;